head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > allOption]<br/>컴포넌트에 '전체 선택'을 의미하는 아이템의 추가 여부를 설정합니다.",
    "validation" : [        
        "'전체 선택' 아이템이 선택된 상태에서 다른 아이템의 선택이 한 개라도 해제되면 '전체 선택' 아이템의 선택 상태도 해제됩니다.",
        "일반 아이템이 모두 선택되면 '전체 선택' 아이템이 자동으로 선택됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        allOption : true,
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["oncheckboxclick"])

    // comp 생성 함수 호출
    $c.gcm.createBasicCheckComboBox(cList, eList);    
}


scwin.btn_getItemInfo_onclick = function (e) {   
    // 해당 class를 가진 모든 input 요소를 선택
    let checkboxElements = document.querySelectorAll('input.w2table_ccb_col_checkbox');

    if (checkboxElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("checkcombobox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    // 각각의 체크박스 요소의 checked 속성 값을 출력
    for (var i = 0; i < checkboxElements.length; i++) {
        let isChecked = checkboxElements[i].checked; // checked 속성 값 가져오기
        wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" checked : " + isChecked);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" index : " + target1.getInfo(i).index);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" label : " + target1.getInfo(i).label);  
        // wf_body_bottom.getObj("scwin").setReturnValue("index="+i+" value : " + target1.getInfo(i).value);  
    }
}
